package com.bettertoppi.topuhud.hud;
import com.bettertoppi.topuhud.config.ConfigManager;import com.bettertoppi.topuhud.config.TopuHudConfig;import com.mojang.blaze3d.platform.InputConstants;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.keymapping.v1.KeyMappingHelper;import net.fabricmc.fabric.api.client.rendering.v1.hud.HudElementRegistry;import net.minecraft.client.KeyMapping;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.Item;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.Items;import net.minecraft.world.effect.MobEffectInstance;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.EntityHitResult;import net.minecraft.core.BlockPos;import net.minecraft.util.Mth;import org.lwjgl.glfw.GLFW;import java.util.ArrayDeque;import java.util.Deque;import java.util.Locale;
public final class HudManager{public enum HudId{ARMOR,FPS,PING,TPS,CPS,COMBO,TOTEM,POTION,EFFECTS,GAPPLE,WARNING,ENEMY,COOLDOWN,BLOCK_OVERLAY,KEYSTROKES,MEMORY}private static KeyMapping editKey,sneakKey;private static boolean editMode,sneakToggled,mouseDown;private static final Deque<Long> clicks=new ArrayDeque<>();private static long lastHit;private static int combo;private static double tps=20;private static long lastTick=System.nanoTime();private HudManager(){}
public static void initialize(){KeyMapping.Category cat=KeyMapping.Category.register(Identifier.fromNamespaceAndPath("topuhud","hud"));editKey=KeyMappingHelper.registerKeyMapping(new KeyMapping("key.topuhud.edit",InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_RIGHT_CONTROL,cat));sneakKey=KeyMappingHelper.registerKeyMapping(new KeyMapping("key.topuhud.sneak",InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_RIGHT_ALT,cat));ClientTickEvents.END_CLIENT_TICK.register(HudManager::tick);HudElementRegistry.addLast(Identifier.fromNamespaceAndPath("topuhud","core_hud"),HudManager::render);}
public static void registerClick(){clicks.addLast(System.currentTimeMillis());}public static void registerHit(){registerClick();lastHit=System.currentTimeMillis();combo++;}public static boolean isEditMode(){return editMode;}public static void setEditMode(boolean v){editMode=v;ConfigManager.get().editMode=v;if(!v)ConfigManager.save();}
private static void tick(Minecraft mc){while(editKey.consumeClick())setEditMode(!editMode);while(sneakKey.consumeClick())sneakToggled=!sneakToggled;long now=System.nanoTime(),dt=now-lastTick;lastTick=now;if(dt>0)tps=Mth.clamp(tps*.94+Math.min(20,1_000_000_000.0/dt)*.06,0,20);long cut=System.currentTimeMillis()-1000;while(!clicks.isEmpty()&&clicks.peekFirst()<cut)clicks.removeFirst();if(System.currentTimeMillis()-lastHit>1500)combo=0;Player p=mc.player;if(p==null)return;TopuHudConfig c=ConfigManager.get();if(c.toggleSneak)p.setCrouching(sneakToggled);if(c.autoSprint&&mc.screen==null&&mc.options.keyUp.isDown()&&!p.isCrouching()&&!p.isPassenger()&&p.getFoodData().getFoodLevel()>6)p.setSprinting(true);boolean left=GLFW.glfwGetMouseButton(mc.getWindow().handle(),GLFW.GLFW_MOUSE_BUTTON_LEFT)==GLFW.GLFW_PRESS;if(left&&!mouseDown&&mc.hitResult instanceof EntityHitResult h&&h.getEntity() instanceof LivingEntity){registerHit();}mouseDown=left;}
private static int[] pos(TopuHudConfig c,HudId id){return switch(id){case ARMOR->new int[]{c.armorX,c.armorY};case FPS->new int[]{c.fpsX,c.fpsY};case PING->new int[]{c.pingX,c.pingY};case TPS->new int[]{c.tpsX,c.tpsY};case CPS->new int[]{c.cpsX,c.cpsY};case COMBO->new int[]{c.comboX,c.comboY};case TOTEM->new int[]{c.totemX,c.totemY};case POTION->new int[]{c.potionX,c.potionY};case EFFECTS->new int[]{c.effectsX,c.effectsY};case GAPPLE->new int[]{c.gappleX,c.gappleY};case WARNING->new int[]{c.warningX,c.warningY};case ENEMY->new int[]{c.enemyHealthX,c.enemyHealthY};case COOLDOWN->new int[]{c.cooldownX,c.cooldownY};case BLOCK_OVERLAY->new int[]{c.blockOverlayX,c.blockOverlayY};case KEYSTROKES->new int[]{c.keystrokesX,c.keystrokesY};case MEMORY->new int[]{c.memoryX,c.memoryY};};}
private static boolean enabled(TopuHudConfig c,HudId id){return switch(id){case ARMOR->c.armorHud;case FPS->c.fpsCounter;case PING->c.pingDisplay;case TPS->c.tpsDisplay;case CPS->c.cpsDisplay;case COMBO->c.comboCounter;case TOTEM->c.totemCounter;case POTION->c.potionCounter;case EFFECTS->c.potionEffects;case GAPPLE->c.gappleCounter;case WARNING->c.armorWarning;case ENEMY->c.enemyHealth;case COOLDOWN->c.cooldown;case BLOCK_OVERLAY->c.blockOverlay;case KEYSTROKES->c.keystrokes;case MEMORY->c.memory;};}public static int[] getPositionForEditor(TopuHudConfig c,HudId id){return pos(c,id);}public static boolean isEnabledForEditor(HudId id){return enabled(ConfigManager.get(),id);}public static int getWidthForEditor(HudId id){return 170;}public static int getHeightForEditor(HudId id){return id==HudId.EFFECTS?80:24;}
private static void setPos(TopuHudConfig c,HudId id,int x,int y){switch(id){case ARMOR->{c.armorX=x;c.armorY=y;}case FPS->{c.fpsX=x;c.fpsY=y;}case PING->{c.pingX=x;c.pingY=y;}case TPS->{c.tpsX=x;c.tpsY=y;}case CPS->{c.cpsX=x;c.cpsY=y;}case COMBO->{c.comboX=x;c.comboY=y;}case TOTEM->{c.totemX=x;c.totemY=y;}case POTION->{c.potionX=x;c.potionY=y;}case EFFECTS->{c.effectsX=x;c.effectsY=y;}case GAPPLE->{c.gappleX=x;c.gappleY=y;}case WARNING->{c.warningX=x;c.warningY=y;}case ENEMY->{c.enemyHealthX=x;c.enemyHealthY=y;}case COOLDOWN->{c.cooldownX=x;c.cooldownY=y;}case BLOCK_OVERLAY->{c.blockOverlayX=x;c.blockOverlayY=y;}case KEYSTROKES->{c.keystrokesX=x;c.keystrokesY=y;}case MEMORY->{c.memoryX=x;c.memoryY=y;}}}public static void setPositionForEditor(TopuHudConfig c,HudId id,int x,int y){setPos(c,id,x,y);}
private static void render(GuiGraphicsExtractor g,net.minecraft.client.DeltaTracker d){Minecraft mc=Minecraft.getInstance();Player p=mc.player;if(p==null||mc.level==null)return;TopuHudConfig c=ConfigManager.get();if(c.armorHud)armor(g,mc,p,c.armorX,c.armorY);if(c.fpsCounter)text(g,mc,"FPS: "+mc.getFps(),c.fpsX,c.fpsY);if(c.pingDisplay)ping(g,mc,c.pingX,c.pingY);if(c.tpsDisplay)text(g,mc,String.format(Locale.ROOT,"TPS*: %.1f",tps),c.tpsX,c.tpsY);if(c.cpsDisplay)text(g,mc,"CPS: "+clicks.size(),c.cpsX,c.cpsY);if(c.comboCounter)text(g,mc,"Combo: "+combo,c.comboX,c.comboY);if(c.totemCounter)text(g,mc,"Totems: "+count(p,Items.TOTEM_OF_UNDYING),c.totemX,c.totemY);if(c.potionCounter)text(g,mc,"Potions: "+(count(p,Items.POTION)+count(p,Items.SPLASH_POTION)+count(p,Items.LINGERING_POTION)),c.potionX,c.potionY);if(c.potionEffects)effects(g,mc,p,c.effectsX,c.effectsY);if(c.gappleCounter)text(g,mc,"Gapples: "+(count(p,Items.GOLDEN_APPLE)+count(p,Items.ENCHANTED_GOLDEN_APPLE)),c.gappleX,c.gappleY);if(c.armorWarning)warning(g,mc,p,c.warningX,c.warningY);if(c.enemyHealth)enemy(g,mc,c.enemyHealthX,c.enemyHealthY);if(c.cooldown)cooldown(g,mc,p,c.cooldownX,c.cooldownY);if(c.blockOverlay)block(g,mc,c.blockOverlayX,c.blockOverlayY);if(c.keystrokes)keys(g,mc,c.keystrokesX,c.keystrokesY);if(c.memory)memory(g,mc,c.memoryX,c.memoryY);if(editMode){g.fill(0,0,mc.getWindow().getGuiScaledWidth(),22,0x77000000);text(g,mc,"TOPU HUD EDIT MODE - RIGHT CTRL TO EXIT",8,5);}}
private static void text(GuiGraphicsExtractor g,Minecraft mc,String s,int x,int y){g.text(mc.font,Component.literal(s),x,y,0xFFFFFFFF,true);}private static int count(Player p,Item item){int n=0;for(int i=0;i<p.getInventory().getContainerSize();i++){ItemStack s=p.getInventory().getItem(i);if(s.is(item))n+=s.getCount();}if(p.getOffhandItem().is(item))n+=p.getOffhandItem().getCount();return n;}private static void armor(GuiGraphicsExtractor g,Minecraft mc,Player p,int x,int y){for(int i=0;i<4;i++){ItemStack s=p.getInventory().getArmor(i);if(!s.isEmpty())text(g,mc,"Armor "+(s.isDamageableItem()?(s.getMaxDamage()-s.getDamageValue())*100/s.getMaxDamage():100)+"%",x,y+i*12);}}private static void ping(GuiGraphicsExtractor g,Minecraft mc,int x,int y){int n=-1;if(mc.getConnection()!=null&&mc.player!=null){var i=mc.getConnection().getPlayerInfo(mc.player.getUUID());if(i!=null)n=i.getLatency();}text(g,mc,"Ping: "+(n<0?"-":n+" ms"),x,y);}private static void effects(GuiGraphicsExtractor g,Minecraft mc,Player p,int x,int y){int yy=y,n=0;for(MobEffectInstance e:p.getActiveEffects()){text(g,mc,e.getEffect().value().getDisplayName().getString()+" "+Math.max(0,e.getDuration()/20)+"s",x,yy);yy+=12;if(++n>=6)break;}}private static void warning(GuiGraphicsExtractor g,Minecraft mc,Player p,int x,int y){for(ItemStack s:p.getInventory().getArmor()){if(s.isDamageableItem()&&((s.getMaxDamage()-s.getDamageValue())*100/s.getMaxDamage())<=40){text(g,mc,"ARMOR LOW",x,y);return;}}}private static void enemy(GuiGraphicsExtractor g,Minecraft mc,int x,int y){if(!(mc.hitResult instanceof EntityHitResult h)||!(h.getEntity() instanceof LivingEntity e))return;float r=Mth.clamp(e.getHealth()/Math.max(1,e.getMaxHealth()),0,1);text(g,mc,String.format(Locale.ROOT,"Enemy HP %.1f / %.1f",e.getHealth(),e.getMaxHealth()),x,y);g.fill(x,y+14,x+(int)(150*r),y+18,r<.3?0xFFFF4444:r<.6?0xFFFFFF55:0xFF55FF55);}private static void cooldown(GuiGraphicsExtractor g,Minecraft mc,Player p,int x,int y){float r=p.getAttackStrengthScale(0);text(g,mc,"Attack: "+Math.round(r*100)+"%",x,y);g.fill(x,y+14,x+(int)(120*r),y+18,0xFF55FF55);}private static void block(GuiGraphicsExtractor g,Minecraft mc,int x,int y){if(mc.hitResult instanceof BlockHitResult h&&mc.level!=null){BlockPos b=h.getBlockPos();text(g,mc,"Block: "+mc.level.getBlockState(b).getBlock().getName().getString(),x,y);}}private static void keys(GuiGraphicsExtractor g,Minecraft mc,int x,int y){text(g,mc,"W "+(mc.options.keyUp.isDown()?"■":"□")+"  A "+(mc.options.keyLeft.isDown()?"■":"□")+"  S "+(mc.options.keyDown.isDown()?"■":"□")+"  D "+(mc.options.keyRight.isDown()?"■":"□"),x,y);text(g,mc,"SPACE "+(mc.options.keyJump.isDown()?"■":"□"),x,y+16);}private static void memory(GuiGraphicsExtractor g,Minecraft mc,int x,int y){Runtime r=Runtime.getRuntime();text(g,mc,"RAM: "+(r.totalMemory()-r.freeMemory())/1048576+" / "+r.maxMemory()/1048576+" MB",x,y);}}
